 * 
 * The SoapClient class provides a client for SOAP 1.1, SOAP 1.2 servers. It can be used in WSDL
 * or non-WSDL mode.
 * @link https://php.net/manual/zh/class.soapclient.php
 */
class SoapClient
{
    /**
     * SoapClient constructor
     * @link https://php.net/manual/en/soapclient.construct.php
     * @param string|null $wsdl <p>
     * URI of the WSDL file or <b>NULL</b> if working in
     * non-WSDL mode.
     * </p>
     * <p>
     * During development, WSDL caching may be disabled by the
     * use of the soap.wsdl_cache_ttl <i>php.ini</i> setting
     * otherwise changes made to the WSDL file will have no effect until
     * soap.wsdl_cache_ttl is expired.
     * </p>
     * @param array $options [optional] <p>
     * An array of options. If working in WSDL mode, this parameter is optional.
     * If working in non-WSDL mode, the location and
     * uri options must be set, where location
     * is the URL of the SOAP server to send the request to, and uri
     * is the target namespace of the SOAP service.
     * </p>
     * <p>
     * The style and use options only work in
     * non-WSDL mode. In WSDL mode, they come from the WSDL file.
     * </p>
     * <p>
     * The soap_version option should be one of either
     * <b>SOAP_1_1</b> or <b>SOAP_1_2</b> to
     * select SOAP 1.1 or 1.2, respectively. If omitted, 1.1 is used.
     * </p>
     * <p>
     * For HTTP authentication, the login and
     * password options can be used to supply credentials.
     * For making an HTTP connection through
     * a proxy server, the options proxy_host,
     * proxy_port, proxy_login
     * and proxy_password are also available.
     * For HTTPS client certificate authentication use
     * local_cert and passphrase options. An
     * authentication may be supplied in the authentication
     * option. The authentication method may be either
     * <b>SOAP_AUTHENTICATION_BASIC</b> (default) or
     * <b>SOAP_AUTHENTICATION_DIGEST</b>.
     * </p>
     * <p>
     * The compression option allows to use compression
     * of HTTP SOAP requests and responses.
     * </p>
     * <p>
     * The encoding option defines internal character
     * encoding. This option does not change the encoding of SOAP requests (it is
     * always utf-8), but converts strings into it.
     * </p>
     * <p>
     * The trace option enables tracing of request so faults
     * can be backtraced. This defaults to <b>FALSE</b>
     * </p>
     * <p>
     * The classmap option can be used to map some WSDL
     * types to PHP classes. This option must be an array with WSDL types
     * as keys and names of PHP classes as values.
     * </p>
     * <p>
     * Setting the boolean trace option enables use of the
     * methods
     * SoapClient->__getLastRequest,
     * SoapClient->__getLastRequestHeaders,
     * SoapClient->__getLastResponse and
     * SoapClient->__getLastResponseHeaders.
     * </p>
     * <p>
     * The exceptions option is a boolean value defining whether
     * soap errors throw exceptions of type
     * SoapFault.
     * </p>
     * <p>
     * The connection_timeout option defines a timeout in seconds
     * for the connection to the SOAP service. This option does not define a timeout
     * for services with slow responses. To limit the time to wait for calls to finish the
     * default_socket_timeout setting
     * is available.
     * </p>
     * <p>
     * The typemap option is an array of type mappings.
     * Type mapping is an array with keys type_name,
     * type_ns (namespace URI), from_xml
     * (callback accepting one string parameter) and to_xml
     * (callback accepting one object parameter).
     * </p>
     * <p>
     * The cache_wsdl option is one of
     * <b>WSDL_CACHE_NONE</b>,
     * <b>WSDL_CACHE_DISK</b>,
     * <b>WSDL_CACHE_MEMORY</b> or
     * <b>WSDL_CACHE_BOTH</b>.
     * </p>
     * <p>
     * The user_agent option specifies string to use in
     * User-Agent header.
     * </p>
     * <p>
     * The stream_context option is a resource
     * for context.
     * </p>
     * <p>
     * The features option is a bitmask of
     * <b>SOAP_SINGLE_ELEMENT_ARRAYS</b>,
     * <b>SOAP_USE_XSI_ARRAY_TYPE</b>,
     * <b>SOAP_WAIT_ONE_WAY_CALLS</b>.
     * </p>
     * <p>
     * The keep_alive option is a boolean value defining whether
     * to send the Connection: Keep-Alive header or
     * Connection: close.
     * </p>
     * <p>
     * The ssl_method option is one of
     * <b>SOAP_SSL_METHOD_TLS</b>,
     * <b>SOAP_SSL_METHOD_SSLv2</b>,
     * <b>SOAP_SSL_METHOD_SSLv3</b> or
     * <b>SOAP_SSL_METHOD_SSLv23</b>.
     * </p>
     * @since 5.0
     *
     * @removed 8.0
     */
    public function SoapClient($wsdl, array $options = null) {}

    /**
 * <div id="soapclient.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__construct</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__construct</span> — <span class="dc-title">SoapClient constructor</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$wsdl</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = []</span></span>)</div>  <p class="para rdfs-comment">   Creates a <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object to connect to a SOAP service.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapclient.construct-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">wsdl</span></dt>     <dd>      <p class="para">       URI of a <span>WSDL</span> file describing the service, which is used to automatically       configure the client. If not provided, the client will operate in non-WSDL       mode.      </p>      <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:        </p><p class="para">        By default, the WSDL file will be cached for performance. To disable        or configure this caching, see        <a href="https://php.net/manual/zh/soap.configuration.php#soap.configuration.list" class="link">SOAP 配置选项</a>        and the <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.cache-wsdl" class="link">        <span class="literal">cache_wsdl</span> option</a>.       </p>      </blockquote>     </dd>             <dt><span class="parameter" style="color:#3A95FF">options</span></dt>     <dd>      <p class="para">       An associative array specifying additional options for the SOAP client.       If <span class="parameter" style="color:#3A95FF">wsdl</span> is provided, this is optional; otherwise,       at least <span class="literal">location</span> and <span class="literal">url</span> must be       provided.       </p><dl>                 <dt id="soapclient.construct.options.location">          <span class="parameter" style="color:#3A95FF">location</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           The URL of the SOAP server to send the request to.          </p>          <p class="para">           Required if the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter is not provided.           If both a <span class="parameter" style="color:#3A95FF">wsdl</span> parameter and           <span class="literal">location</span> option are provided, the           <span class="literal">location</span> option will over-ride any location           specified in the WSDL file.          </p>         </dd>                         <dt id="soapclient.construct.options.uri">          <span class="parameter" style="color:#3A95FF">uri</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           The target namespace of the SOAP service.          </p>          <p class="para">           Required if the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter is not provided;           ignored otherwise.          </p>         </dd>                         <dt id="soapclient.construct.options.style">          <span class="parameter" style="color:#3A95FF">style</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Specifies the binding style to use for this client, using the constants           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-rpc">SOAP_RPC</a></span></strong> and <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-document">SOAP_DOCUMENT</a></span></strong>.           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-rpc">SOAP_RPC</a></span></strong> indicates RPC-style binding, where the           SOAP request body contains a standard encoding of a function call.           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-document">SOAP_DOCUMENT</a></span></strong> indicates document-style binding,           where the SOAP request body contains an XML document with           service-defined meaning.          </p>          <p class="para">           If the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter is provided, this           option is ignored, and the style is read from the WSDL file.          </p>          <p class="para">           If neither this option nor the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter           is provided, RPC-style is used.          </p>         </dd>                         <dt id="soapclient.construct.options.use">          <span class="parameter" style="color:#3A95FF">use</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Specifies the encoding style to use for this client, using the           constants <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-encoded">SOAP_ENCODED</a></span></strong> or <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-literal">SOAP_LITERAL</a></span></strong>.           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-encoded">SOAP_ENCODED</a></span></strong> indicates encoding using the types           defined in the SOAP specification.           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-literal">SOAP_LITERAL</a></span></strong> indicates encoding using a schema           defined by the service.          </p>          <p class="para">           If the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter is provided, this           option is ignored, and the encoding is read from the WSDL file.          </p>          <p class="para">           If neither this option nor the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter           is provided, the "encoded" style is used.          </p>         </dd>                         <dt id="soapclient.construct.options.soap-version">          <span class="parameter" style="color:#3A95FF">soap_version</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Specifies the version of the SOAP protocol to use:           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-1-1">SOAP_1_1</a></span></strong> for SOAP 1.1,           or <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-1-2">SOAP_1_2</a></span></strong> for SOAP 1.2.          </p>          <p class="para">           If omitted, SOAP 1.1 is used.          </p>         </dd>                         <dt id="soapclient.construct.options.authentication">          <span class="parameter" style="color:#3A95FF">authentication</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Specifies the authentication method when using HTTP authentication           in requests. The value may be either           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-authentication-basic">SOAP_AUTHENTICATION_BASIC</a></span></strong>           or <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-authentication-digest">SOAP_AUTHENTICATION_DIGEST</a></span></strong>.          </p>          <p class="para">           If omitted, and the <span class="literal">login</span> option is provided,           Basic Authentication is used.          </p>         </dd>                         <dt id="soapclient.construct.options.login">          <span class="parameter" style="color:#3A95FF">login</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Username to use with HTTP Basic or Digest Authentication.          </p>         </dd>                         <dt id="soapclient.construct.options.password">          <span class="parameter" style="color:#3A95FF">password</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Password to use with HTTP Basic or Digest Authentication.          </p>          <p class="para">           Not to be confused with <span class="literal">passphrase</span>,           which is used with HTTPS Client Certificate authentication.          </p>         </dd>                         <dt id="soapclient.construct.options.local-cert">          <span class="parameter" style="color:#3A95FF">local_cert</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Path to a client certificate for use with HTTPS authentication.           It must be a <span>PEM</span> encoded file which contains the certificate           and private key.          </p>          <p class="para">           The file can also include a chain of issuers, which must come           after the client certificate.          </p>          <p class="para">           Can also be set via           <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.stream-context" class="link">           <span class="parameter" style="color:#3A95FF">stream_context</span></a>,           which also supports specifying a separate private key file.          </p>         </dd>                         <dt id="soapclient.construct.options.passphrase">          <span class="parameter" style="color:#3A95FF">passphrase</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Passphrase for the client certificate specified in the           <span class="literal">local_cert</span> option.          </p>          <p class="para">           Not to be confused with <span class="literal">password</span>,           which is used for Basic or Digest Authentication.          </p>          <p class="para">           Can also be set via           <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.stream-context" class="link">           <span class="parameter" style="color:#3A95FF">stream_context</span></a>.          </p>         </dd>                         <dt id="soapclient.construct.options.proxy-host">          <span class="parameter" style="color:#3A95FF">proxy_host</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Hostname to use as a proxy server for HTTP requests.          </p>          <p class="para">           The <span class="literal">proxy_port</span> option must also be specified.          </p>         </dd>                         <dt id="soapclient.construct.options.proxy-port">          <span class="parameter" style="color:#3A95FF">proxy_port</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           TCP port to use when connecting to the proxy server           specified in <span class="literal">proxy_host</span>.          </p>         </dd>                         <dt id="soapclient.construct.options.proxy-login">          <span class="parameter" style="color:#3A95FF">proxy_login</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Optional username to authenticate with the proxy server           specified in <span class="literal">proxy_host</span>, using HTTP           Basic Authentication.          </p>         </dd>                         <dt id="soapclient.construct.options.proxy-password">          <span class="parameter" style="color:#3A95FF">proxy_password</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Optional password to authenticate with the proxy server           specified in <span class="literal">proxy_host</span>, using HTTP           Basic Authentication.          </p>         </dd>                         <dt id="soapclient.construct.options.compression">          <span class="parameter" style="color:#3A95FF">compression</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Enables compression of HTTP SOAP requests and responses.          </p>          <p class="para">           The value should be the bitwise OR of three parts:           an optional <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-compression-accept">SOAP_COMPRESSION_ACCEPT</a></span></strong>,           to send an "Accept-Encoding" header; either           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-compression-gzip">SOAP_COMPRESSION_GZIP</a></span></strong>           or <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-compression-deflate">SOAP_COMPRESSION_DEFLATE</a></span></strong> to indicate           the compression algorithm to use; and a number between 1 and 9           to indicate the level of compression to use in the request.           For example, to enable two-way gzip compression with the maximum           compression level, use           <span class="literal">SOAP_COMPRESSION_ACCEPT | SOAP_COMPRESSION_GZIP | 9</span>.          </p>         </dd>                         <dt id="soapclient.construct.options.encoding">          <span class="parameter" style="color:#3A95FF">encoding</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Defines the internal character encoding. Requests are always sent           in UTF-8, and converted to and from this encoding.          </p>         </dd>                         <dt id="soapclient.construct.options.trace">          <span class="parameter" style="color:#3A95FF">trace</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>         </dt>         <dd>          <p class="para">           Captures request and response information, which can then be           accessed with the methods           <span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastRequest()}</span>,           <span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastRequestHeaders()}</span>,           <span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastResponse()}</span>,           and <span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastResponseHeaders()}</span>.          </p>          <p class="para">           If omitted, defaults to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>          </p>         </dd>                         <dt id="soapclient.construct.options.classmap">          <span class="parameter" style="color:#3A95FF">classmap</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>         </dt>         <dd>          <p class="para">           Used to map types defined in the WSDL to PHP classes.           It should be specified as an associative <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> with           type names from the WSDL as keys and names of PHP classes as values.           Note that the type name of an element is not necessarily the same as           the element (tag) name.          </p>          <p class="para">           The provided class names should always be fully qualified with any           <a href="https://php.net/manual/zh/language.namespaces.php" class="link">namespaces</a>, and never           start with a leading <span class="literal">\</span>. The correct form can be           generated by using           {@link ::class}.          </p>          <p class="para">           Note that when creating a class, the constructor will not be called,           but magic <a href="https://php.net/manual/zh/language.oop5.overloading.php#object.set" class="link">__set()</a> and           <a href="https://php.net/manual/zh/language.oop5.overloading.php#object.get" class="link">__get()</a> methods for individual           properties will be.          </p>         </dd>                         <dt id="soapclient.construct.options.typemap">          <span class="parameter" style="color:#3A95FF">typemap</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>         </dt>         <dd>          <p class="para">           Used to define type mappings using user-defined callback functions.           Each type mapping should be an array with keys           <span class="literal">type_name</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> specifying the           XML element type);           <span class="literal">type_ns</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> containing namespace           URI);           <span class="literal">from_xml</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> accepting one           string parameter and returning an object) and           <span class="literal">to_xml</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> accepting one           object parameter and returning a string).          </p>         </dd>                         <dt id="soapclient.construct.options.exceptions">          <span class="parameter" style="color:#3A95FF">exceptions</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>         </dt>         <dd>          <p class="para">           Defines whether errors throw exceptions of type           <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span>.          </p>          <p class="para">           Defaults to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>          </p>         </dd>                         <dt id="soapclient.construct.options.connection-timeout">          <span class="parameter" style="color:#3A95FF">connection_timeout</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           Defines a timeout in seconds for the connection to the SOAP service.           This option does not define a timeout for services with slow responses.           To limit the time to wait for calls to finish the           <a href="https://php.net/manual/zh/filesystem.configuration.php#ini.default-socket-timeout" class="link">default_socket_timeout</a>           configuration option is available.          </p>         </dd>                         <dt id="soapclient.construct.options.cache-wsdl">          <span class="parameter" style="color:#3A95FF">cache_wsdl</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           If the <span class="parameter" style="color:#3A95FF">wsdl</span> parameter is provided, and the           <a href="https://php.net/manual/zh/soap.configuration.php#ini.soap.wsdl-cache-enabled" class="link">soap.wsdl_cache_enabled</a>           configuration option is on, this option determines the type of caching.           One of <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-none">WSDL_CACHE_NONE</a></span></strong>,           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-disk">WSDL_CACHE_DISK</a></span></strong>,           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-memory">WSDL_CACHE_MEMORY</a></span></strong> or           <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-both">WSDL_CACHE_BOTH</a></span></strong>.          </p>          <p class="para">           Two types of cache are available: in-memory caching, which caches the WSDL           in the memory of the current process; and disk caching, which caches the           WSDL in a file on disk, shared between all processes.           The directory to use for the disk cache is determined by the           <a href="https://php.net/manual/zh/soap.configuration.php#ini.soap.wsdl-cache-dir" class="link">soap.wsdl_cache_dir</a>           configuration option.           Both caches use the same lifetime, determined by the           <a href="https://php.net/manual/zh/soap.configuration.php#ini.soap.wsdl-cache-ttl" class="link">soap.wsdl_cache_ttl</a>           configuration option. The in-memory cache also has a maximum number of entries           determined by the           <a href="https://php.net/manual/zh/soap.configuration.php#ini.soap.wsdl-cache-limit" class="link">soap.wsdl_cache_limit</a>           configuration option.          </p>          <p class="para">           If not specified, the <a href="https://php.net/manual/zh/soap.configuration.php#ini.soap.wsdl-cache" class="link">           soap.wsdl_cache</a> configuration option will be used.          </p>         </dd>                         <dt id="soapclient.construct.options.user-agent">          <span class="parameter" style="color:#3A95FF">user_agent</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           The value to use in the <span class="literal">User-Agent</span> HTTP header           when making requests.          </p>          <p class="para">           Can also be set via <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.stream-context" class="link">           <span class="parameter" style="color:#3A95FF">stream_context</span></a>.          </p>          <p class="para">           If not specified, the user agent will be <span class="literal">"PHP-SOAP/"</span>           followed by the value of <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.php-version">PHP_VERSION</a></span></strong>.          </p>         </dd>                         <dt id="soapclient.construct.options.stream-context">          <span class="parameter" style="color:#3A95FF">stream_context</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.resource.php" class="type resource" style="color:#EAB766">resource</a></span>         </dt>         <dd>          <p class="para">           A <a href="https://php.net/manual/zh/context.php" class="link">stream context</a> created by           <span class="function">{@link stream_context_create()}</span>, which allows additional           options to be set.          </p>          <p class="para">           The context may include <a href="https://php.net/manual/zh/context.socket.php" class="link">socket context options</a>,           <a href="https://php.net/manual/zh/context.ssl.php" class="link">SSL context options</a>,           plus selected <a href="https://php.net/manual/zh/context.http.php" class="link">HTTP context options</a>:           <span class="literal">content_type</span>, <span class="literal">header</span>,           <span class="literal">max_redirects</span>, <span class="literal">protocol_version</span>,           and <span class="literal">user_agent</span>.          </p>          <p class="para">           Note that the following HTTP headers are generated automatically or from other           options, and will be ignored if specified in the <span class="literal">'header'</span>           context option: <span class="literal">host</span>, <span class="literal">connection</span>,           <span class="literal">user-agent</span>, <span class="literal">content-length</span>,           <span class="literal">content-type</span>, <span class="literal">cookie</span>,           <span class="literal">authorization</span>, and <span class="literal">proxy-authorization</span>          </p>         </dd>                         <dt id="soapclient.construct.options.features">          <span class="parameter" style="color:#3A95FF">features</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>         </dt>         <dd>          <p class="para">           A bitmask to enable one or more of the following features:           </p><dl>                         <dt>              <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-single-element-arrays">SOAP_SINGLE_ELEMENT_ARRAYS</a></span></strong>             </dt>             <dd>              <p class="para">               When decoding a response to an array, the default behaviour is to detect whether               an element name appears once or multiple times in a particular parent element.               For elements which appear only once, an object property allows direct access to               the content; for elements which appear more than once, the property contains an               array with the content of each matching element.              </p>              <p class="para">               If the <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-single-element-arrays">SOAP_SINGLE_ELEMENT_ARRAYS</a></span></strong> feature is enabled,               elements which appear only once are placed in a single-element array, so that               access is consistent for all elements. This only has an effect when using a WSDL               containing a schema for the response. See Examples section for an illustration.              </p>             </dd>                                     <dt>              <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-use-xsi-array-type">SOAP_USE_XSI_ARRAY_TYPE</a></span></strong>             </dt>             <dd>              <p class="para">               When the <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.use" class="link"><span class="literal">use</span>               option</a> or WSDL property is set to <span class="literal">encoded</span>,               force arrays to use a type of <span class="literal">SOAP-ENC:Array</span>, rather than a               schema-specific type.              </p>             </dd>                                     <dt>              <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-wait-one-way-calls">SOAP_WAIT_ONE_WAY_CALLS</a></span></strong>             </dt>             <dd>              <p class="para">               Wait for a response even if the WSDL indicates a one-way request.              </p>             </dd>                       </dl>                   </dd>                         <dt id="soapclient.construct.options.keep-alive">          <span class="parameter" style="color:#3A95FF">keep_alive</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>         </dt>         <dd>          <p class="para">           a boolean value defining whether           to send the <span class="literal">Connection: Keep-Alive</span> header or           <span class="literal">Connection: close</span>.          </p>          <p class="para">           Defaults to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>          </p>         </dd>                         <dt id="soapclient.construct.options.ssl-method">          <span class="parameter" style="color:#3A95FF">ssl_method</span>          <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>         </dt>         <dd>          <p class="para">           Specifies the SSL or TLS protocol version to use with secure HTTP           connections, instead of the default negotiation.           Specifying <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-ssl-method-sslv2">SOAP_SSL_METHOD_SSLv2</a></span></strong>           or <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-ssl-method-sslv3">SOAP_SSL_METHOD_SSLv3</a></span></strong> will force use of SSL 2           or SSL 3, respectively.           Specifying <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-ssl-method-sslv23">SOAP_SSL_METHOD_SSLv23</a></span></strong> has no effect;           the constant exists only for backwards compatibility.           As of PHP 7.2.0, specifying <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-ssl-method-tls">SOAP_SSL_METHOD_TLS</a></span></strong>           also has no effect; in earlier versions, it forced use of TLS 1.0.          </p>          <p class="para">           Note that SSL versions 2 and 3 are considered insecure, and may not           be supported by the installed OpenSSL library.          </p>          <p class="para">           This option is <strong>deprecated</strong> as of PHP 8.1.0.           A more flexible alternative, which allows specifying           individual versions of TLS, is to use the           <a href="https://php.net/manual/zh/soapclient.construct.php#soapclient.construct.options.stream-context" class="link">           <span class="parameter" style="color:#3A95FF">stream_context</span></a> option with           the 'crypto_method' context parameter.           </p><div class="informalexample">            <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #FF8000">// Specifying use of TLS 1.3 only<br></span><span style="color: #9876AA">\$context </span><span style="color: #007700">= </span><span style="color: #9876AA">stream_context_create</span><span style="color: #007700">([<br>    </span><span style="color: #DD0000">'ssl' </span><span style="color: #007700">=&gt; [<br>        </span><span style="color: #DD0000">'crypto_method' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">STREAM_CRYPTO_METHOD_TLSv1_3_CLIENT<br>     </span><span style="color: #007700">]<br>]);<br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, [</span><span style="color: #DD0000">'context' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$context</span><span style="color: #007700">]);</span></span></blockquote></div>            </div>           </div>                   </dd>               </dl>           </dd>       </dl>   </div> <div class="refsect1 errors" id="refsect1-soapclient.construct-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="methodname" style="color:#CC7832"><strong>SoapClient::__construct()</strong></span> will generate an   <strong><span><a href="https://php.net/manual/zh/errorfunc.constants.php#constant.e-error">E_ERROR</a></span></strong> error if the <span class="literal">location</span> and   <span class="literal">uri</span> options aren't provided in non-WSDL mode.  </p>  <p class="para">   A <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> exception will be thrown if the   <span class="parameter" style="color:#3A95FF">wsdl</span> URI cannot be loaded.  </p> </div> <div class="refsect1 examples" id="refsect1-soapclient.construct-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1      <span class="methodname" style="color:#CC7832"><strong>SoapClient::__construct()</strong></span> example    </strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'soap_version'   </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_1_2</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'login'          </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"some_name"</span><span style="color: #007700">,<br>                                            </span><span style="color: #DD0000">'password'       </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"some_password"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'proxy_host'     </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"localhost"</span><span style="color: #007700">,<br>                                            </span><span style="color: #DD0000">'proxy_port'     </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">8080</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'proxy_host'     </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"localhost"</span><span style="color: #007700">,<br>                                            </span><span style="color: #DD0000">'proxy_port'     </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">8080</span><span style="color: #007700">,<br>                                            </span><span style="color: #DD0000">'proxy_login'    </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"some_name"</span><span style="color: #007700">,<br>                                            </span><span style="color: #DD0000">'proxy_password' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"some_password"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'local_cert'     </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"cert_key.pem"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'style'    </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_DOCUMENT</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'use'      </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_LITERAL</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">,<br>  array(</span><span style="color: #DD0000">'compression' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_COMPRESSION_ACCEPT </span><span style="color: #007700">| </span><span style="color: #9876AA">SOAP_COMPRESSION_GZIP </span><span style="color: #007700">| </span><span style="color: #9876AA">9</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'encoding'</span><span style="color: #007700">=&gt;</span><span style="color: #DD0000">'ISO-8859-1'</span><span style="color: #007700">));<br><br>class </span><span style="color: #9876AA">MyBook </span><span style="color: #007700">{<br>    public </span><span style="color: #9876AA">\$title</span><span style="color: #007700">;<br>    public </span><span style="color: #9876AA">\$author</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"books.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'classmap' </span><span style="color: #007700">=&gt; array(</span><span style="color: #DD0000">'book' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"MyBook"</span><span style="color: #007700">)));<br><br></span><span style="color: #9876AA">\$typemap </span><span style="color: #007700">= array(<br>    array(</span><span style="color: #DD0000">"type_ns"  </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://schemas.example.com"</span><span style="color: #007700">,<br>         </span><span style="color: #DD0000">"type_name" </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"book"</span><span style="color: #007700">,<br>         </span><span style="color: #DD0000">"from_xml"  </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"unserialize_book"</span><span style="color: #007700">,<br>         </span><span style="color: #DD0000">"to_xml"    </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"serialize_book"</span><span style="color: #007700">)<br>);<br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"books.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'typemap' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$typemap</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>    <p class="para">   </p><div class="example" id="example-2">    <p><strong>示例 #2 Using the <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-single-element-arrays">SOAP_SINGLE_ELEMENT_ARRAYS</a></span></strong> feature</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #FF8000">// Assuming a response like this, and an appropriate WSDL:<br>&lt;?xml version="1.0" encoding="UTF-8"?&gt;<br>&lt;SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns="urn:example"&gt;<br>    &lt;SOAP-ENV:Body&gt;<br>        &lt;response&gt;<br>            &lt;collection&gt;<br>                &lt;item&gt;Single&lt;/item&gt;<br>            &lt;/collection&gt;<br>            &lt;collection&gt;<br>                &lt;item&gt;First&lt;/item&gt;<br>                &lt;item&gt;Second&lt;/item&gt;<br>            &lt;/collection&gt;<br>        &lt;/response&gt;<br>    &lt;/SOAP-ENV:Body&gt;<br>&lt;/SOAP-ENV:Envelope&gt;<br><br><br></span><span style="color: #007700">echo </span><span style="color: #DD0000">"Default:\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">TestSoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">__DIR__ </span><span style="color: #007700">. </span><span style="color: #DD0000">'/temp.wsdl'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">exampleRequest</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">( </span><span style="color: #9876AA">\$response</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">collection</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">]-&gt;</span><span style="color: #9876AA">item </span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">( </span><span style="color: #9876AA">\$response</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">collection</span><span style="color: #007700">[</span><span style="color: #9876AA">1</span><span style="color: #007700">]-&gt;</span><span style="color: #9876AA">item </span><span style="color: #007700">);<br><br>echo </span><span style="color: #DD0000">"\nWith SOAP_SINGLE_ELEMENT_ARRAYS:\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">TestSoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">__DIR__ </span><span style="color: #007700">. </span><span style="color: #DD0000">'/temp.wsdl'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'features' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_SINGLE_ELEMENT_ARRAYS</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">exampleRequest</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">( </span><span style="color: #9876AA">\$response</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">collection</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">]-&gt;</span><span style="color: #9876AA">item </span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">( </span><span style="color: #9876AA">\$response</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">collection</span><span style="color: #007700">[</span><span style="color: #9876AA">1</span><span style="color: #007700">]-&gt;</span><span style="color: #9876AA">item </span><span style="color: #007700">);</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Default:<br>string(6)&nbsp;"Single"<br>array(2)&nbsp;{<br>&nbsp;&nbsp;[0]&nbsp;=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"First"<br>&nbsp;&nbsp;[1]&nbsp;=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"Second"<br>}<br><br>With&nbsp;SOAP_SINGLE_ELEMENT_ARRAYS:<br>array(1)&nbsp;{<br>&nbsp;&nbsp;[0]&nbsp;=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"Single"<br>}<br>array(2)&nbsp;{<br>&nbsp;&nbsp;[0]&nbsp;=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"First"<br>&nbsp;&nbsp;[1]&nbsp;=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"Second"<br>}</blockquote></div>    </div>   </div>   </div></div>
 * 
     * SoapClient constructor
     * @link https://php.net/manual/zh/soapclient.construct.php
     * @param string|null $wsdl <p>
     * URI of the WSDL file or <b>NULL</b> if working in
     * non-WSDL mode.
     * </p>
     * <p>
     * During development, WSDL caching may be disabled by the
     * use of the soap.wsdl_cache_ttl <i>php.ini</i> setting
     * otherwise changes made to the WSDL file will have no effect until
     * soap.wsdl_cache_ttl is expired.
     * </p>
     * @param array $options [optional] <p>
     * An array of options. If working in WSDL mode, this parameter is optional.
     * If working in non-WSDL mode, the location and
     * uri options must be set, where location
     * is the URL of the SOAP server to send the request to, and uri
     * is the target namespace of the SOAP service.
     * </p>
     * <p>
     * The style and use options only work in
     * non-WSDL mode. In WSDL mode, they come from the WSDL file.
     * </p>
     * <p>
     * The soap_version option should be one of either
     * <b>SOAP_1_1</b> or <b>SOAP_1_2</b> to
     * select SOAP 1.1 or 1.2, respectively. If omitted, 1.1 is used.
     * </p>
     * <p>
     * For HTTP authentication, the login and
     * password options can be used to supply credentials.
     * For making an HTTP connection through
     * a proxy server, the options proxy_host,
     * proxy_port, proxy_login
     * and proxy_password are also available.
     * For HTTPS client certificate authentication use
     * local_cert and passphrase options. An
     * authentication may be supplied in the authentication
     * option. The authentication method may be either
     * <b>SOAP_AUTHENTICATION_BASIC</b> (default) or
     * <b>SOAP_AUTHENTICATION_DIGEST</b>.
     * </p>
     * <p>
     * The compression option allows to use compression
     * of HTTP SOAP requests and responses.
     * </p>
     * <p>
     * The encoding option defines internal character
     * encoding. This option does not change the encoding of SOAP requests (it is
     * always utf-8), but converts strings into it.
     * </p>
     * <p>
     * The trace option enables tracing of request so faults
     * can be backtraced. This defaults to <b>FALSE</b>
     * </p>
     * <p>
     * The classmap option can be used to map some WSDL
     * types to PHP classes. This option must be an array with WSDL types
     * as keys and names of PHP classes as values.
     * </p>
     * <p>
     * Setting the boolean trace option enables use of the
     * methods
     * SoapClient->__getLastRequest,
     * SoapClient->__getLastRequestHeaders,
     * SoapClient->__getLastResponse and
     * SoapClient->__getLastResponseHeaders.
     * </p>
     * <p>
     * The exceptions option is a boolean value defining whether
     * soap errors throw exceptions of type
     * SoapFault.
     * </p>
     * <p>
     * The connection_timeout option defines a timeout in seconds
     * for the connection to the SOAP service. This option does not define a timeout
     * for services with slow responses. To limit the time to wait for calls to finish the
     * default_socket_timeout setting
     * is available.
     * </p>
     * <p>
     * The typemap option is an array of type mappings.
     * Type mapping is an array with keys type_name,
     * type_ns (namespace URI), from_xml
     * (callback accepting one string parameter) and to_xml
     * (callback accepting one object parameter).
     * </p>
     * <p>
     * The cache_wsdl option is one of
     * <b>WSDL_CACHE_NONE</b>,
     * <b>WSDL_CACHE_DISK</b>,
     * <b>WSDL_CACHE_MEMORY</b> or
     * <b>WSDL_CACHE_BOTH</b>.
     * </p>
     * <p>
     * The user_agent option specifies string to use in
     * User-Agent header.
     * </p>
     * <p>
     * The stream_context option is a resource
     * for context.
     * </p>
     * <p>
     * The features option is a bitmask of
     * <b>SOAP_SINGLE_ELEMENT_ARRAYS</b>,
     * <b>SOAP_USE_XSI_ARRAY_TYPE</b>,
     * <b>SOAP_WAIT_ONE_WAY_CALLS</b>.
     * </p>
     * <p>
     * The keep_alive option is a boolean value defining whether
     * to send the Connection: Keep-Alive header or
     * Connection: close.
     * </p>
     * <p>
     * The ssl_method option is one of
     * <b>SOAP_SSL_METHOD_TLS</b>,
     * <b>SOAP_SSL_METHOD_SSLv2</b>,
     * <b>SOAP_SSL_METHOD_SSLv3</b> or
     * <b>SOAP_SSL_METHOD_SSLv23</b>.
     * </p>
     * @throws SoapFault A SoapFault exception will be thrown if the wsdl URI cannot be loaded.
     * @since 5.0
     */
    public function __construct(
        #[LanguageLevelTypeAware(['8.0' => 'string|null'], default: '')] $wsdl,
        array $options = []
    ) {}

    /**
 * <div id="soapclient.call" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__call</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__call</span> — <span class="dc-title">Calls a SOAP function (deprecated)</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.call-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__call</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$args</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">   Calling this method directly is deprecated. Usually, SOAP functions can be   called as methods of the <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object; in   situations where this is not possible or additional options are needed, use   <span class="methodname" style="color:#CC7832">{@link SoapClient::__soapCall()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapclient.call-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The name of the SOAP function to call.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">args</span></dt>     <dd>      <p class="para">       An array of the arguments to pass to the function.       This can be either an ordered or an associative array.       Note that most SOAP servers require parameter names to be provided, in which case this must be an associative array.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.call-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   SOAP functions may return one, or multiple values. If only one value is   returned by the SOAP function, the return value will be a scalar.   If multiple values are returned, an associative array of named output   parameters is returned instead.  </p>  <p class="para">   On error, if the <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object was constructed   with the <span class="literal">exceptions</span> option set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>,   a <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> object will be returned.  </p> </div></div>
 * 
     * @link https://php.net/manual/zh/soapclient.call.php
     * @param string $name
     * @param array $args
     * @return mixed
     * @since 5.0
     */
    #[Deprecated]
    #[TentativeType]
    public function __call(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $name,
        array $args
    ): mixed {}

    /**
 * <div id="soapclient.soapcall" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__soapCall</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__soapCall</span> — <span class="dc-title">Calls a SOAP function</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.soapcall-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__soapCall</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$args</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.soapheader.php" class="type SoapHeader" style="color:#EAB766">SoapHeader</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span> <span class="parameter" style="color:#3A95FF">\$inputHeaders</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$outputHeaders</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">   This is a low level API function that is used to make a SOAP call. Usually,   in WSDL mode, SOAP functions can be called as methods of the   <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object. This method is useful in non-WSDL   mode when <span class="literal">soapaction</span> is unknown, <span class="literal">uri</span>   differs from the default or when sending and/or receiving SOAP Headers.  </p>  <p class="para">   On error, a call to a SOAP function can cause PHP to throw exceptions or return a   <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> object if exceptions are disabled.   To check if the function call failed to catch the SoapFault exceptions,   check the result with <span class="function">{@link is_soap_fault()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapclient.soapcall-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The name of the SOAP function to call.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">args</span></dt>     <dd>      <p class="para">       An array of the arguments to pass to the function. This can be either       an ordered or an associative array. Note that most SOAP servers require       parameter names to be provided, in which case this must be an       associative array.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">options</span></dt>     <dd>      <p class="para">       An associative array of options to pass to the client.      </p>      <p class="para">       The <span class="literal">location</span> option is the URL of the remote Web service.      </p>      <p class="para">       The <span class="literal">uri</span> option is the target namespace of the SOAP service.      </p>      <p class="para">        The <span class="literal">soapaction</span> option is the action to call.      </p>    </dd>             <dt><span class="parameter" style="color:#3A95FF">inputHeaders</span></dt>     <dd>      <p class="para">       An array of headers to be sent along with the SOAP request.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">outputHeaders</span></dt>     <dd>      <p class="para">       If supplied, this array will be filled with the headers from the SOAP response.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.soapcall-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   SOAP functions may return one, or multiple values. If only one value is   returned by the SOAP function, the return value will be a scalar.   If multiple values are returned, an associative array of named output   parameters is returned instead.  </p>  <p class="para">   On error, if the <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object was constructed   with the <span class="literal">exceptions</span> option set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>,   a <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> object will be returned.  </p> </div> <div class="refsect1 examples" id="refsect1-soapclient.soapcall-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>SoapClient::__soapCall()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"SomeFunction"</span><span style="color: #007700">, array(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"SomeFunction"</span><span style="color: #007700">, array(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">), </span><span style="color: #9876AA">NULL</span><span style="color: #007700">,<br>                    new </span><span style="color: #9876AA">SoapHeader</span><span style="color: #007700">(), </span><span style="color: #9876AA">\$output_headers</span><span style="color: #007700">);<br><br><br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"SomeFunction"</span><span style="color: #007700">, array(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"SomeFunction"</span><span style="color: #007700">, array(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">),<br>                    array(</span><span style="color: #DD0000">'soapaction' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'some_action'</span><span style="color: #007700">,<br>                          </span><span style="color: #DD0000">'uri'        </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'some_uri'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapclient.soapcall-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__construct()} - SoapClient constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapParam::__construct()} - SoapParam constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapVar::__construct()} - SoapVar constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapHeader::__construct()} - SoapHeader constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapFault::__construct()} - SoapFault constructor</span></li>    <li><span class="function">{@link is_soap_fault()} - Checks if a SOAP call has failed</span></li>   </ul>   </div></div>
 * 
     * Calls a SOAP function
     * @link https://php.net/manual/zh/soapclient.soapcall.php
     * @param string $name <p>
     * The name of the SOAP function to call.
     * </p>
     * @param array $args <p>
     * An array of the arguments to pass to the function. This can be either
     * an ordered or an associative array. Note that most SOAP servers require
     * parameter names to be provided, in which case this must be an
     * associative array.
     * </p>
     * @param array $options [optional] <p>
     * An associative array of options to pass to the client.
     * </p>
     * <p>
     * The location option is the URL of the remote Web service.
     * </p>
     * <p>
     * The uri option is the target namespace of the SOAP service.
     * </p>
     * <p>
     * The soapaction option is the action to call.
     * </p>
     * @param mixed $inputHeaders [optional] <p>
     * An array of headers to be sent along with the SOAP request.
     * </p>
     * @param array &$outputHeaders [optional] <p>
     * If supplied, this array will be filled with the headers from the SOAP response.
     * </p>
     * @return mixed SOAP functions may return one, or multiple values. If only one value is returned
     * by the SOAP function, the return value of __soapCall will be
     * a simple value (e.g. an integer, a string, etc). If multiple values are
     * returned, __soapCall will return
     * an associative array of named output parameters.
     * </p>
     * <p>
     * On error, if the SoapClient object was constructed with the exceptions
     * option set to <b>FALSE</b>, a SoapFault object will be returned. If this
     * option is not set, or is set to <b>TRUE</b>, then a SoapFault object will
     * be thrown as an exception.
     * @throws SoapFault A SoapFault exception will be thrown if an error occurs
     * and the SoapClient was constructed with the exceptions option not set, or
     * set to <b>TRUE</b>.
     * @since 5.0
     */
    #[TentativeType]
    public function __soapCall(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $name,
        array $args,
        #[LanguageLevelTypeAware(['8.0' => 'array|null'], default: '')] $options = null,
        $inputHeaders = null,
        &$outputHeaders = null
    ): mixed {}

    /**
 * <div id="soapclient.getlastrequest" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__getLastRequest</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__getLastRequest</span> — <span class="dc-title">Returns last SOAP request</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.getlastrequest-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__getLastRequest</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="para rdfs-comment">   Returns the XML sent in the last SOAP request.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    This method works only if the <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object    was created with the <span class="literal">trace</span> option set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.   </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapclient.getlastrequest-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.getlastrequest-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The last SOAP request, as an XML string.  </p> </div> <div class="refsect1 examples" id="refsect1-soapclient.getlastrequest-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 SoapClient::__getLastRequest() example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'trace' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">();<br>echo </span><span style="color: #DD0000">"REQUEST:\n" </span><span style="color: #007700">. </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__getLastRequest</span><span style="color: #007700">() . </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapclient.getlastrequest-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastRequestHeaders()} - Returns the SOAP headers from the last request</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastResponse()} - Returns last SOAP response</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__getLastResponseHeaders()} - Returns the SOAP headers from the last response</span></li>   </ul>   </div></div>
 * 
     * Returns last SOAP request
     * @link https://php.net/manual/zh/soapclient.getlastrequest.php
     * @return string|null The last SOAP request, as an XML string.
     * @since 5.0
     */
    #[TentativeType]
    public function __getLastRequest(): ?string {}

