    /**
 * <div id="soapclient.dorequest" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__doRequest</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__doRequest</span> — <span class="dc-title">Performs a SOAP request</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.dorequest-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__doRequest</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$request</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$location</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$action</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$version</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$oneWay</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$uriParserClass</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span><br>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="para rdfs-comment">   Performs SOAP request over HTTP.  </p>  <p class="para">   This method can be overridden in subclasses to implement different transport   layers, perform additional XML processing or other purpose.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapclient.dorequest-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">request</span></dt>     <dd>      <p class="para">       The XML SOAP request.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">location</span></dt>     <dd>      <p class="para">       The URL to request.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">action</span></dt>     <dd>      <p class="para">       The SOAP action.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">version</span></dt>     <dd>      <p class="para">       The SOAP version.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">oneWay</span></dt>     <dd>      <p class="para">       If <span class="parameter" style="color:#3A95FF">oneWay</span> is set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, this method returns nothing.       Use this where a response is not expected.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">uriParserClass</span></dt>     <dd>      <span class="simpara">       The classname to use for parsing the redirection URI when a <span class="literal">"Location"</span> header is received in the response,       or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> to use the default, <span class="function">{@link parse_url()}</span> based parsing.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.dorequest-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The XML SOAP response.  </p> </div> <div class="refsect1 changelog" id="refsect1-soapclient.dorequest-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.5.0</td>      <td>       The optional parameter <span class="parameter" style="color:#3A95FF">uriParserClass</span> has been added.      </td>     </tr>     <tr>      <td>8.0.0</td>      <td>       The type of <span class="parameter" style="color:#3A95FF">oneWay</span> is <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> now; formerly it was <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-soapclient.dorequest-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapClient::__doRequest()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">function </span><span style="color: #9876AA">Add</span><span style="color: #007700">(</span><span style="color: #9876AA">\$x</span><span style="color: #007700">, </span><span style="color: #9876AA">\$y</span><span style="color: #007700">)<br>{<br>    return </span><span style="color: #9876AA">\$x </span><span style="color: #007700">+ </span><span style="color: #9876AA">\$y</span><span style="color: #007700">;<br>}<br><br>class </span><span style="color: #9876AA">LocalSoapClient </span><span style="color: #007700">extends </span><span style="color: #9876AA">SoapClient<br></span><span style="color: #007700">{<br>    private </span><span style="color: #9876AA">\$server</span><span style="color: #007700">;<br><br>    public function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wsdl</span><span style="color: #007700">, </span><span style="color: #9876AA">\$options</span><span style="color: #007700">)<br>    {<br>        </span><span style="color: #9876AA">parent</span><span style="color: #007700">::</span><span style="color: #9876AA">__construct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wsdl</span><span style="color: #007700">, </span><span style="color: #9876AA">\$options</span><span style="color: #007700">);<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #9876AA">\$wsdl</span><span style="color: #007700">, </span><span style="color: #9876AA">\$options</span><span style="color: #007700">);<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(</span><span style="color: #DD0000">'Add'</span><span style="color: #007700">);<br>    }<br><br>    public function </span><span style="color: #9876AA">__doRequest</span><span style="color: #007700">(<br>        </span><span style="color: #9876AA">\$request</span><span style="color: #007700">,<br>        </span><span style="color: #9876AA">\$location</span><span style="color: #007700">,<br>        </span><span style="color: #9876AA">\$action</span><span style="color: #007700">,<br>        </span><span style="color: #9876AA">\$version</span><span style="color: #007700">,<br>        </span><span style="color: #9876AA">\$one_way </span><span style="color: #007700">= </span><span style="color: #9876AA">false</span><span style="color: #007700">,<br>    ): ?</span><span style="color: #9876AA">string </span><span style="color: #007700">{<br>        </span><span style="color: #9876AA">ob_start</span><span style="color: #007700">();<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">handle</span><span style="color: #007700">(</span><span style="color: #9876AA">\$request</span><span style="color: #007700">);<br>        </span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">ob_get_contents</span><span style="color: #007700">();<br>        </span><span style="color: #9876AA">ob_end_clean</span><span style="color: #007700">();<br><br>        return </span><span style="color: #9876AA">\$response</span><span style="color: #007700">;<br>    }<br>}<br><br></span><span style="color: #9876AA">\$x </span><span style="color: #007700">= new </span><span style="color: #9876AA">LocalSoapClient</span><span style="color: #007700">(<br>    </span><span style="color: #9876AA">null</span><span style="color: #007700">,<br>    [<br>        </span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'test://'</span><span style="color: #007700">,<br>        </span><span style="color: #DD0000">'uri' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'http://testuri.org'</span><span style="color: #007700">,<br>    ]<br>);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$x</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">Add</span><span style="color: #007700">(</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div></div>
 * 
     * Performs a SOAP request
     * @link https://php.net/manual/zh/soapclient.dorequest.php
     * @param string $request <p>
     * The XML SOAP request.
     * </p>
     * @param string $location <p>
     * The URL to request.
     * </p>
     * @param string $action <p>
     * The SOAP action.
     * </p>
     * @param int $version <p>
     * The SOAP version.
     * </p>
     * @param bool|int $oneWay [optional] <p>
     * If $oneWay is set to 1, this method returns nothing.
     * Use this where a response is not expected.
     * </p>
     * @return string|null The XML SOAP response.
     * @since 5.0
     */
    #[TentativeType]
    public function __doRequest(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $request,
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $location,
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $action,
        #[LanguageLevelTypeAware(['8.0' => 'int'], default: '')] $version,
        #[LanguageLevelTypeAware(["8.0" => 'bool'], default: 'int')] $oneWay = false,
        #[PhpStormStubsElementAvailable(from: '8.5')] ?string $uriParserClass = null
    ): ?string {}

    /**
 * <div id="soapclient.setcookie" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__setCookie</h1>  <p class="verinfo">(PHP 5 &gt;= 5.0.4, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__setCookie</span> — <span class="dc-title">Defines a cookie for SOAP requests</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.setcookie-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__setCookie</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$value</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Defines a cookie to be sent along with the SOAP requests.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    Calling this method will affect all following calls to     <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> methods.   </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapclient.setcookie-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The name of the cookie.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">value</span></dt>     <dd>      <p class="para">       The value of the cookie. If not specified, the cookie will be deleted.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.setcookie-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">  没有返回值。  </p> </div> <div class="refsect1 changelog" id="refsect1-soapclient.setcookie-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">value</span> is now nullable.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
     * The __setCookie purpose
     * @link https://php.net/manual/zh/soapclient.setcookie.php
     * @param string $name <p>
     * The name of the cookie.
     * </p>
     * @param string $value [optional] <p>
     * The value of the cookie. If not specified, the cookie will be deleted.
     * </p>
     * @return void No value is returned.
     * @since 5.0
     */
    #[TentativeType]
    public function __setCookie(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $name,
        #[LanguageLevelTypeAware(["8.0" => "string|null"], default: "string")] $value = null
    ): void {}

    /**
 * <div id="soapclient.setlocation" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapClient::__setLocation</h1>  <p class="verinfo">(PHP 5 &gt;= 5.0.4, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapClient::__setLocation</span> — <span class="dc-title">Sets the location of the Web service to use</span></p> </div> <div class="refsect1 description" id="refsect1-soapclient.setlocation-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapClient::__setLocation</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$location</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="para rdfs-comment">   Sets the endpoint URL that will be touched by following SOAP requests. This is equivalent to   specifying the <span class="literal">location</span> option when constructing the SoapClient.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    Calling this method is optional.  The SoapClient uses the endpoint from    the WSDL file by default.   </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapclient.setlocation-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">location</span></dt>     <dd>      <p class="para">       The new endpoint URL.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapclient.setlocation-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The old endpoint URL.  </p> </div> <div class="refsect1 changelog" id="refsect1-soapclient.setlocation-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.3</td>      <td>       <span class="parameter" style="color:#3A95FF">location</span> is nullable now.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-soapclient.setlocation-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapClient::__setLocation()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://example.com/webservice.php?wsdl'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__setLocation</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://www.somethirdparty.com'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$old_location </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__setLocation</span><span style="color: #007700">(); </span><span style="color: #FF8000">// unsets the location option<br><br></span><span style="color: #007700">echo </span><span style="color: #9876AA">\$old_location</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例的输出类似于：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">http://www.somethirdparty.com</blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapclient.setlocation-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__construct()} - SoapClient constructor</span></li>   </ul>   </div></div>
 * 
     * Sets the location of the Web service to use
     * @link https://php.net/manual/zh/soapclient.setlocation.php
     * @param string $location [optional] <p>
     * The new endpoint URL.
     * </p>
     * @return string|null The old endpoint URL.
     * @since 5.0
     */
    #[TentativeType]
    public function __setLocation(#[LanguageLevelTypeAware(['8.0' => 'string|null'], default: '')] $location = null): ?string {}

    /**
