><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$header </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapHeader</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://soapinterop.org/echoheader/'</span><span style="color: #007700">, <br>                            </span><span style="color: #DD0000">'echoMeStringRequest'</span><span style="color: #007700">,<br>                            </span><span style="color: #DD0000">'hello world'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__setSoapHeaders</span><span style="color: #007700">(</span><span style="color: #9876AA">\$header</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"echoVoid"</span><span style="color: #007700">, </span><span style="color: #9876AA">null</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>      <p class="para">     </p><div class="example" id="example-2">      <p><strong>示例 #2 Set Multiple Headers</strong></p>      <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$headers </span><span style="color: #007700">= array();<br><br></span><span style="color: #9876AA">\$headers</span><span style="color: #007700">[] = new </span><span style="color: #9876AA">SoapHeader</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://soapinterop.org/echoheader/'</span><span style="color: #007700">, <br>                            </span><span style="color: #DD0000">'echoMeStringRequest'</span><span style="color: #007700">,<br>                            </span><span style="color: #DD0000">'hello world'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$headers</span><span style="color: #007700">[] = new </span><span style="color: #9876AA">SoapHeader</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://soapinterop.org/echoheader/'</span><span style="color: #007700">, <br>                            </span><span style="color: #DD0000">'echoMeStringRequest'</span><span style="color: #007700">,<br>                            </span><span style="color: #DD0000">'hello world again'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__setSoapHeaders</span><span style="color: #007700">(</span><span style="color: #9876AA">\$headers</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"echoVoid"</span><span style="color: #007700">, </span><span style="color: #9876AA">null</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>      </div>     </div>     </div></div>
