t1-soapvar.construct-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapVar::__construct()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">class </span><span style="color: #9876AA">SOAPStruct </span><span style="color: #007700">{<br>    function </span><span style="color: #9876AA">SOAPStruct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$s</span><span style="color: #007700">, </span><span style="color: #9876AA">\$i</span><span style="color: #007700">, </span><span style="color: #9876AA">\$f</span><span style="color: #007700">)<br>    {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">varString </span><span style="color: #007700">= </span><span style="color: #9876AA">\$s</span><span style="color: #007700">;<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">varInt </span><span style="color: #007700">= </span><span style="color: #9876AA">\$i</span><span style="color: #007700">;<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">varFloat </span><span style="color: #007700">= </span><span style="color: #9876AA">\$f</span><span style="color: #007700">;<br>    }<br>}<br></span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$struct </span><span style="color: #007700">= new </span><span style="color: #9876AA">SOAPStruct</span><span style="color: #007700">(</span><span style="color: #DD0000">'arg'</span><span style="color: #007700">, </span><span style="color: #9876AA">34</span><span style="color: #007700">, </span><span style="color: #9876AA">325.325</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$soapstruct </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapVar</span><span style="color: #007700">(</span><span style="color: #9876AA">\$struct</span><span style="color: #007700">, </span><span style="color: #9876AA">SOAP_ENC_OBJECT</span><span style="color: #007700">, </span><span style="color: #DD0000">"SOAPStruct"</span><span style="color: #007700">, </span><span style="color: #DD0000">"http://soapinterop.org/xsd"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">echoStruct</span><span style="color: #007700">(new </span><span style="color: #9876AA">SoapParam</span><span style="color: #007700">(</span><span style="color: #9876AA">\$soapstruct</span><span style="color: #007700">, </span><span style="color: #DD0000">"inputStruct"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapvar.construct-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p