/**
 * <div id="class.soapserver" class="reference"> <h1 class="title">The SoapServer class</h1>  <div class="partintro"><p class="verinfo">(PHP 5, PHP 7, PHP 8)</p>  <div class="section" id="soapserver.intro">   <h2 class="title">简介</h2>   <p class="para">    The SoapServer class provides a server for the <a href="http://www.w3.org/TR/soap11/" class="link external">»&nbsp;SOAP 1.1</a>    and <a href="http://www.w3.org/TR/soap12/" class="link external">»&nbsp;SOAP 1.2</a> protocols. It can be    used with or without a WSDL service description.   </p>  </div>  <div class="section" id="soapserver.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">class</span> <strong class="classname"><strong class="classname">SoapServer</strong></strong>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">private</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.soapfault.php" class="type SoapFault" style="color:#EAB766">SoapFault</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.soapserver.php#soapserver.props.soap-fault">\$<var class="varname">__soap_fault</var></a></var><span class="initializer"> = null</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="http