aram"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span><span class="initializer"> = ""</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$lang</span><span class="initializer"> = ""</span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.getfunctions.php" class="methodname" style="color:#CC7832">getFunctions</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.getlastresponse.php" class="methodname" style="color:#CC7832">__getLastResponse</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.handle.php" class="methodname" style="color:#CC7832">handle</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$request</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.setclass.php" class="methodname" style="color:#CC7832">setClass</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$class</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$args</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.setobject.php" class="methodname" style="color:#CC7832">setObject</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> <span class="parameter" style="color:#3A95FF">\$object</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapserver.setpersistence.php" class="methodname" style="color:#CC7832">setPersistence</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="soapserver.props">   <h2 class="title">属性</h2>   <dl>         <dt id="soapserver.props.service"><var class="varname">service</var></dt>     <dd>      <p class="para">      </p>     </dd>             <dt id="soapserver.props.soap-fault"><var class="varname">__soap_fault</var></dt>     <dd>      <p class="para">      </p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link SoapServer::addFunction} — 添加一个或多个函数来处理 SOAP 请求</li><li>{@link SoapServer::addSoapHeader} — Add a SOAP header to the response</li><li>{@link SoapServer::__construct} — SoapServer constructor</li><li>{@link SoapServer::fault} — Issue SoapServer fault indicating an error</li><li>{@link SoapServer::getFunctions} — Returns list of defined functions</li><li>{@link SoapServer::__getLastResponse} — Returns last SOAP response</li><li>{@link SoapServer::handle} — Handles a SOAP request</li><li>{@link SoapServer::setClass} — Sets the class which handles SOAP requests</li><li>{@link SoapServer::setObject} — Sets the object which will be used to handle SOAP requests</li><li>{@link SoapServer::setPersistence} — Sets SoapServer persistence mode</li></ul></div>
 * 
 * The SoapServer class provides a server for the SOAP 1.1 and SOAP 1.2 protocols. It can be used with or without a WSDL service description.
 * @link https://php.net/manual/zh/class.soapserver.php
 */
class SoapServer
{
    /**
 * <div id="soapserver.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::__construct</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::__construct</span> — <span class="dc-title">SoapServer constructor</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$wsdl</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = []</span></span>)</div>  <p class="para rdfs-comment">   This constructor allows the creation of <span class="classname"><a href="https://php.net/manual/zh/class.soapserver.php" class="classname">SoapServer</a></span>   objects in WSDL or non-WSDL mode.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.construct-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">wsdl</span></dt>     <dd>      <p class="para">       To use the SoapServer in WSDL mode, pass the URI of a WSDL file.       Otherwise, pass <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> and set the <span class="literal">uri</span> option to the       target namespace for the server.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">options</span></dt>     <dd>      <p class="para">       Allow setting a default SOAP version (<span class="literal">soap_version</span>),       internal character encoding (<span class="literal">encoding</span>),       and actor URI (<span class="literal">actor</span>).      </p>      <p class="para">       The <span class="literal">classmap</span> option can be used to map some WSDL       types to PHP classes. This option must be an array with WSDL types       as keys and names of PHP classes as values.      </p>      <p class="para">       The <span class="literal">typemap</span> option is an array of type mappings.       Type mapping is an array with keys <span class="literal">type_name</span>,       <span class="literal">type_ns</span> (namespace URI), <span class="literal">from_xml</span>       (callback accepting one string parameter) and <span class="literal">to_xml</span>       (callback accepting one object parameter).      </p>      <p class="para">       The <span class="literal">cache_wsdl</span> option is one of       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-none">WSDL_CACHE_NONE</a></span></strong>,       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-disk">WSDL_CACHE_DISK</a></span></strong>,       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-memory">WSDL_CACHE_MEMORY</a></span></strong> or       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.wsdl-cache-both">WSDL_CACHE_BOTH</a></span></strong>.      </p>      <p class="para">       There is also a <span class="literal">features</span> option which can be set to       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-wait-one-way-calls">SOAP_WAIT_ONE_WAY_CALLS</a></span></strong>,       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-single-element-arrays">SOAP_SINGLE_ELEMENT_ARRAYS</a></span></strong>,       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-use-xsi-array-type">SOAP_USE_XSI_ARRAY_TYPE</a></span></strong>.      </p>      <p class="para">       The <span class="literal">send_errors</span> option can be set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> to sent a       generic error message ("Internal error") instead of the specific error       message sent otherwise.      </p>     </dd>       </dl>   </div> <div class="refsect1 examples" id="refsect1-soapserver.construct-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapServer::__construct()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'soap_version' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">SOAP_1_2</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'actor' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://example.org/ts-tests/C"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'encoding'</span><span style="color: #007700">=&gt;</span><span style="color: #DD0000">'ISO-8859-1'</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'uri' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br><br>class </span><span style="color: #9876AA">MyBook </span><span style="color: #007700">{<br>    public </span><span style="color: #9876AA">\$title</span><span style="color: #007700">;<br>    public </span><span style="color: #9876AA">\$author</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"books.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'classmap' </span><span style="color: #007700">=&gt; array(</span><span style="color: #DD0000">'book' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"MyBook"</span><span style="color: #007700">)));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapserver.construct-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__construct()} - SoapClient constructor</span></li>   </ul>   </div></div>
 * 
     * SoapServer constructor
     * @link https://php.net/manual/zh/soapserver.soapserver.php
     * @param mixed $wsdl <p>
     * To use the SoapServer in WSDL mode, pass the URI of a WSDL file.
     * Otherwise, pass <b>NULL</b> and set the uri option to the
     * target namespace for the server.
     * </p>
     * @param array $options [optional] <p>
     * Allow setting a default SOAP version (soap_version),
     * internal character encoding (encoding),
     * and actor URI (actor).
     * </p>
     * <p>
     * The classmap option can be used to map some WSDL
     * types to PHP classes. This option must be an array with WSDL types
     * as keys and names of PHP classes as values.
     * </p>
     * <p>
     * The typemap option is an array of type mappings.
     * Type mapping is an array with keys type_name,
     * type_ns (namespace URI), from_xml
     * (callback accepting one string parameter) and to_xml
     * (callback accepting one object parameter).
     * </p>
     * <p>
     * The cache_wsdl option is one of
     * <b>WSDL_CACHE_NONE</b>,
     * <b>WSDL_CACHE_DISK</b>,
     * <b>WSDL_CACHE_MEMORY</b> or
     * <b>WSDL_CACHE_BOTH</b>.
     * </p>
     * <p>
     * There is also a features option which can be set to
     * <b>SOAP_WAIT_ONE_WAY_CALLS</b>,
     * <b>SOAP_SINGLE_ELEMENT_ARRAYS</b>,
     * <b>SOAP_USE_XSI_ARRAY_TYPE</b>.
     * </p>
     * @since 5.0
     */
    public function __construct(
        #[LanguageLevelTypeAware(['8.0' => 'string|null'], default: '')] $wsdl,
        array $options = []
    ) {}

    /**
     * SoapServer constructor
     * @link https://php.net/manual/en/soapserver.soapserver.php
     * @param mixed $wsdl <p>
     * To use the SoapServer in WSDL mode, pass the URI of a WSDL file.
     * Otherwise, pass <b>NULL</b> and set the uri option to the
     * target namespace for the server.
     * </p>
     * @param array $options [optional] <p>
     * Allow setting a default SOAP version (soap_version),
     * internal character encoding (encoding),
     * and actor URI (actor).
     * </p>
     * <p>
     * The classmap option can be used to map some WSDL
     * types to PHP classes. This option must be an array with WSDL types
     * as keys and names of PHP classes as values.
     * </p>
     * <p>
     * The typemap option is an array of type mappings.
     * Type mapping is an array with keys type_name,
     * type_ns (namespace URI), from_xml
     * (callback accepting one string parameter) and to_xml
     * (callback accepting one object parameter).
     * </p>
     * <p>
     * The cache_wsdl option is one of
     * <b>WSDL_CACHE_NONE</b>,
     * <b>WSDL_CACHE_DISK</b>,
     * <b>WSDL_CACHE_MEMORY</b> or
     * <b>WSDL_CACHE_BOTH</b>.
     * </p>
     * <p>
     * There is also a features option which can be set to
     * <b>SOAP_WAIT_ONE_WAY_CALLS</b>,
     * <b>SOAP_SINGLE_ELEMENT_ARRAYS</b>,
     * <b>SOAP_USE_XSI_ARRAY_TYPE</b>.
     * </p>
     * @since 5.0
     * @removed 8.0
     */
    public function SoapServer($wsdl, array $options = null) {}

    /**
 * <div id="soapserver.setpersistence" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::setPersistence</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::setPersistence</span> — <span class="dc-title">Sets SoapServer persistence mode</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.setpersistence-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::setPersistence</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    This function allows changing the persistence state of a SoapServer object between   requests. This function allows saving data between requests utilizing PHP sessions.  This method   only has an affect on a SoapServer after it has exported functions utilizing <span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()}</span>.   </p>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">      The persistence of <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-persistence-session">SOAP_PERSISTENCE_SESSION</a></span></strong> makes only     objects of the given class persistent, but not the class static data. In this      case, use <var class="varname">\$this-&gt;bar</var> instead of self::\$bar.     </p>   </blockquote>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">     <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-persistence-session">SOAP_PERSISTENCE_SESSION</a></span></strong> serializes data on the class object between requests. In order to properly utilize resources (e.g. <span class="classname"><a href="https://php.net/manual/zh/class.pdo.php" class="classname">PDO</a></span>), <a href="https://php.net/manual/zh/language.oop5.magic.php#object.wakeup" class="link">__wakeup()</a> and <a href="https://php.net/manual/zh/language.oop5.magic.php#object.sleep" class="link">__sleep()</a> magic methods should be utilized.     </p>    </blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapserver.setpersistence-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">mode</span></dt>     <dd>      <p class="para">       One of the <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-persistence-session">SOAP_PERSISTENCE_<span class="replaceable">*</span></a></span></strong> constants.      </p>      <p class="para">       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-persistence-request">SOAP_PERSISTENCE_REQUEST</a></span></strong> - SoapServer data does not persist between       requests. This is the <strong>default</strong> behavior of any SoapServer       object after setClass is called.       </p>      <p class="para">       <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-persistence-session">SOAP_PERSISTENCE_SESSION</a></span></strong> - SoapServer data persists between requests.       This is accomplished by serializing the SoapServer class data into       <var class="varname"><a href="https://php.net/manual/zh/reserved.variables.session.php" class="classname">\$_SESSION['_bogus_session_name']</a></var>, because of this        <span class="function">{@link session_start()}</span> must be called before this persistence mode is set.       </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.setpersistence-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div>  <div class="refsect1 examples" id="refsect1-soapserver.setpersistence-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapServer::setPersistence()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br> </span><span style="color: #007700">class </span><span style="color: #9876AA">MyFirstPersistentSoapServer </span><span style="color: #007700">{<br>     private </span><span style="color: #9876AA">\$resource</span><span style="color: #007700">; </span><span style="color: #FF8000">// (Such as PDO, mysqli, etc..)<br>     </span><span style="color: #007700">public </span><span style="color: #9876AA">\$myvar1</span><span style="color: #007700">;<br>     public </span><span style="color: #9876AA">\$myvar2</span><span style="color: #007700">;<br><br>     public function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">() {<br>         </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__wakeup</span><span style="color: #007700">(); </span><span style="color: #FF8000">// We're calling our wakeup to handle starting our resource<br>     </span><span style="color: #007700">}<br><br>     public function </span><span style="color: #9876AA">__wakeup</span><span style="color: #007700">() {<br>         </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">resource </span><span style="color: #007700">= </span><span style="color: #9876AA">CodeToStartOurResourceUp</span><span style="color: #007700">();<br>     }<br><br>     public function </span><span style="color: #9876AA">__sleep</span><span style="color: #007700">() {<br>         </span><span style="color: #FF8000">// We make sure to leave out \$resource here, so our session data remains persistent<br>         // Failure to do so will result in the failure during the unserialization of data<br>         // on the next request; thus, our SoapObject would not be persistent across requests.<br>         </span><span style="color: #007700">return array(</span><span style="color: #DD0000">'myvar1'</span><span style="color: #007700">,</span><span style="color: #DD0000">'myvar2'</span><span style="color: #007700">);<br>     }<br> }<br><br> try {<br>     </span><span style="color: #9876AA">session_start</span><span style="color: #007700">();<br>     </span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'uri' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$_SERVER</span><span style="color: #007700">[</span><span style="color: #DD0000">'REQUEST_URI'</span><span style="color: #007700">]));<br>     </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">setClass</span><span style="color: #007700">(</span><span style="color: #DD0000">'MyFirstPersistentSoapServer'</span><span style="color: #007700">);<br>     </span><span style="color: #FF8000">// setPersistence MUST be called after setClass, because setClass's<br>     // behavior sets SESSION_PERSISTENCE_REQUEST upon enacting the method.<br>     </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">setPersistence</span><span style="color: #007700">(</span><span style="color: #9876AA">SOAP_PERSISTENCE_SESSION</span><span style="color: #007700">);<br>     </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">handle</span><span style="color: #007700">();<br> } catch(</span><span style="color: #9876AA">SoapFault \$e</span><span style="color: #007700">) {<br>     </span><span style="color: #9876AA">error_log</span><span style="color: #007700">(</span><span style="color: #DD0000">"SOAP ERROR: "</span><span style="color: #007700">. </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">());<br> }<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div>  <div class="refsect1 seealso" id="refsect1-soapserver.setpersistence-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()} - Sets the class which handles SOAP requests</span></li>   </ul>   </div></div>
 * 
     * Sets SoapServer persistence mode
     * @link https://php.net/manual/zh/soapserver.setpersistence.php
     * @param int $mode <p>
     * One of the SOAP_PERSISTENCE_XXX constants.
     * </p>
     * <p>
     * <b>SOAP_PERSISTENCE_REQUEST</b> - SoapServer data does not persist between
     * requests. This is the default behavior of any SoapServer
     * object after setClass is called.
     * </p>
     * <p>
     * <b>SOAP_PERSISTENCE_SESSION</b> - SoapServer data persists between requests.
     * This is accomplished by serializing the SoapServer class data into
     * $_SESSION['_bogus_session_name'], because of this
     * <b>session_start</b> must be called before this persistence mode is set.
     * </p>
     * @return void No value is returned.
     * @since 5.1
     */
    #[TentativeType]
    public function setPersistence(#[LanguageLevelTypeAware(['8.0' => 'int'], default: '')] $mode): void {}

    /**
 * <div id="soapserver.setclass" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::setClass</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::setClass</span> — <span class="dc-title">Sets the class which handles SOAP requests</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.setclass-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::setClass</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$class</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$args</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Exports all methods from specified class.  </p>  <p class="para">   The object can be made persistent across request for a given PHP session   with the <span class="methodname" style="color:#CC7832">{@link SoapServer::setPersistence()}</span> method.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.setclass-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">class</span></dt>     <dd>      <p class="para">       The name of the exported class.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">args</span></dt>     <dd>      <p class="para">       These optional parameters will be passed to the default class constructor       during object creation.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.setclass-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 seealso" id="refsect1-soapserver.setclass-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::__construct()} - SoapServer constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::addFunction()} - 添加一个或多个函数来处理 SOAP 请求</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::setPersistence()} - Sets SoapServer persistence mode</span></li>   </ul>   </div></div>
 * 
     * Sets the class which handles SOAP requests
     * @link https://php.net/manual/zh/soapserver.setclass.php
     * @param string $class <p>
     * The name of the exported class.
     * </p>
     * @param mixed ...$args [optional] These optional parameters will be passed to the default class constructor during object creation.
     * @return void No value is returned.
     * @since 5.0
     */
    #[TentativeType]
    public function setClass(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $class,
        #[LanguageLevelTypeAware(['8.0' => 'mixed'], default: '')] ...$args
    ): void {}

    /**
 * <div id="soapserver.setobject" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::setObject</h1>  <p class="verinfo">(PHP 5 &gt;= 5.2.0, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::setObject</span> — <span class="dc-title">Sets the object which will be used to handle SOAP requests</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.setobject-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::setObject</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> <span class="parameter" style="color:#3A95FF">\$object</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   This sets a specific object as the handler for SOAP requests, rather than just a class as in   <span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.setobject-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">object</span></dt>     <dd>      <p class="para">       The object to handle the requests.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.setobject-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 seealso" id="refsect1-soapserver.setobject-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()} - Sets the class which handles SOAP requests</span></li>   </ul>   </div></div>
 * 
     * Sets the object which will be used to handle SOAP requests
     * @link https://php.net/manual/zh/soapserver.setobject.php
     * @param object $object <p>
     * The object to handle the requests.
     * </p>
     * @return void No value is returned.
     */
    #[TentativeType]
    public function setObject(#[LanguageLevelTypeAware(['8.0' => 'object'], default: '')] $object): void {}

    /**
 * <div id="soapserver.addfunction" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::addFunction</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::addFunction</span> — <span class="dc-title">添加一个或多个函数来处理 SOAP 请求</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.addfunction-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::addFunction</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$functions</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   为远程客户端导出一个或多个函数  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.addfunction-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">functions</span></dt>     <dd>      <p class="para">       导出一个函数，将函数名作为字符串传递给这个参数。      </p>      <p class="para">       导出多个函数，将一组函数名作为数组传递。      </p>      <p class="para">       导出所有函数，传递特殊常量 <strong><span><a href="https://php.net/manual/zh/soap.constants.php#constant.soap-functions-all">SOAP_FUNCTIONS_ALL</a></span></strong>.      </p>      <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:        </p><p class="para">        <span class="parameter" style="color:#3A95FF">functions</span> 接收的所有输入参数必须同时和 WSDL        文件中定义的顺序一样（它们不应该接收任何输出变量作为参数）并且返回一个或多个值。如果要返回多个值，它们必须返回一组被命名的输出参数作为数组。       </p>      </blockquote>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.addfunction-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-soapserver.addfunction-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapServer::addFunction()</strong></span> 示例</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">function </span><span style="color: #9876AA">echoString</span><span style="color: #007700">(</span><span style="color: #9876AA">\$inputString</span><span style="color: #007700">)<br>{<br>    return </span><span style="color: #9876AA">\$inputString</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(</span><span style="color: #DD0000">"echoString"</span><span style="color: #007700">);<br><br>function </span><span style="color: #9876AA">echoTwoStrings</span><span style="color: #007700">(</span><span style="color: #9876AA">\$inputString1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$inputString2</span><span style="color: #007700">)<br>{<br>    return array(</span><span style="color: #DD0000">"outputString1" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$inputString1</span><span style="color: #007700">,<br>                 </span><span style="color: #DD0000">"outputString2" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$inputString2</span><span style="color: #007700">);<br>}<br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(array(</span><span style="color: #DD0000">"echoString"</span><span style="color: #007700">, </span><span style="color: #DD0000">"echoTwoStrings"</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(</span><span style="color: #9876AA">SOAP_FUNCTIONS_ALL</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapserver.addfunction-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::__construct()} - SoapServer constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()} - Sets the class which handles SOAP requests</span></li>   </ul>   </div></div>
 * 
     * Adds one or more functions to handle SOAP requests
     * @link https://php.net/manual/zh/soapserver.addfunction.php
     * @param mixed $functions <p>
     * To export one function, pass the function name into this parameter as
     * a string.
     * </p>
     * <p>
     * To export several functions, pass an array of function names.
     * </p>
     * <p>
     * To export all the functions, pass a special constant <b>SOAP_FUNCTIONS_ALL</b>.
     * </p>
     * <p>
     * <i>functions</i> must receive all input arguments in the same
     * order as defined in the WSDL file (They should not receive any output parameters
     * as arguments) and return one or more values. To return several values they must
     * return an array with named output parameters.
     * </p>
     * @return void No value is returned.
     * @since 5.0
     */
    #[TentativeType]
    public function addFunction($functions): void {}

    /**
 * <div id="soapserver.getfunctions" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::getFunctions</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::getFunctions</span> — <span class="dc-title">Returns list of defined functions</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.getfunctions-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::getFunctions</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">    Returns a list of the defined functions in the SoapServer object.   This method returns the list of all functions added by   <span class="methodname" style="color:#CC7832">{@link SoapServer::addFunction()}</span> or   <span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.getfunctions-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.getfunctions-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   An <span class="literal">array</span> of the defined functions.  </p> </div> <div class="refsect1 examples" id="refsect1-soapserver.getfunctions-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapServer::getFunctions()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #9876AA">NULL</span><span style="color: #007700">, array(</span><span style="color: #DD0000">"uri" </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(</span><span style="color: #9876AA">SOAP_FUNCTIONS_ALL</span><span style="color: #007700">);<br>if (</span><span style="color: #9876AA">\$_SERVER</span><span style="color: #007700">[</span><span style="color: #DD0000">"REQUEST_METHOD"</span><span style="color: #007700">] == </span><span style="color: #DD0000">"POST"</span><span style="color: #007700">) {<br>  </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">handle</span><span style="color: #007700">();<br>} else {<br>  echo </span><span style="color: #DD0000">"This SOAP server can handle following functions: "</span><span style="color: #007700">;<br>  </span><span style="color: #9876AA">\$functions </span><span style="color: #007700">= </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getFunctions</span><span style="color: #007700">();<br>  foreach(</span><span style="color: #9876AA">\$functions </span><span style="color: #007700">as </span><span style="color: #9876AA">\$func</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$func </span><span style="color: #007700">. </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>  }<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapserver.getfunctions-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::__construct()} - SoapServer constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::addFunction()} - 添加一个或多个函数来处理 SOAP 请求</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::setClass()} - Sets the class which handles SOAP requests</span></li>   </ul>   </div></div>
 * 
     * Returns list of defined functions
     * @link https://php.net/manual/zh/soapserver.getfunctions.php
     * @return array An array of the defined functions.
     * @since 5.0
     */
    #[TentativeType]
    public function getFunctions(): array {}

    /**
 * <div id="soapserver.handle" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::handle</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::handle</span> — <span class="dc-title">Handles a SOAP request</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.handle-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::handle</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$request</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Processes a SOAP request, calls necessary functions, and sends a response   back.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapserver.handle-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">request</span></dt>     <dd>      <p class="para">       The SOAP request. If this argument is omitted, the request is assumed to be       in the raw POST data of the HTTP request.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.handle-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 changelog" id="refsect1-soapserver.handle-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">request</span> is now nullable.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-soapserver.handle-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapServer::handle()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">function </span><span style="color: #9876AA">test</span><span style="color: #007700">(</span><span style="color: #9876AA">\$x</span><span style="color: #007700">)<br>{<br>    return </span><span style="color: #9876AA">\$x</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'uri' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addFunction</span><span style="color: #007700">(</span><span style="color: #DD0000">"test"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">handle</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapserver.handle-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapServer::__construct()} - SoapServer constructor</span></li>   </ul>   </div></div>
 * 
     * Handles a SOAP request
     * @link https://php.net/manual/zh/soapserver.handle.php
     * @param string $request [optional] <p>
     * The SOAP request. If this argument is omitted, the request is assumed to be
     * in the raw POST data of the HTTP request.
     * </p>
     * @return void No value is returned.
     * @since 5.0
     */
    #[TentativeType]
    public function handle(#[LanguageLevelTypeAware(['8.0' => 'string|null'], default: '')] $request = null): void {}

    /**
 * <div id="soapserver.fault" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::fault</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapServer::fault</span> — <span class="dc-title">Issue SoapServer fault indicating an error</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.fault-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::fault</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$code</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$string</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$actor</span><span class="initializer"> = ""</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$details</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span><span class="initializer"> = ""</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$lang</span><span class="initializer"> = ""</span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Sends a response to the client of the current request indicating an error.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    This can only be called when handling a request.   </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapserver.fault-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">code</span></dt>     <dd>      <p class="para">       The error code to return      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">string</span></dt>     <dd>      <p class="para">       A brief description of the error      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">actor</span></dt>     <dd>      <p class="para">       A string identifying the actor that caused the fault.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">details</span></dt>     <dd>      <p class="para">       More details of the fault      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The name of the fault. This can be used to select a name from a WSDL file.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">lang</span></dt>     <dd>      <span class="simpara">The human language that the SoapFault is written in. This is only used for SOAP version 1.2.</span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.fault-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 changelog" id="refsect1-soapserver.fault-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.5.0</td>      <td>       The optional parameter <span class="parameter" style="color:#3A95FF">lang</span> has been added       in order to be compliant with the SOAP 1.2 specification.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-soapserver.fault-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapFault::__construct()} - SoapFault constructor</span></li>   </ul>   </div></div>
 * 
     * Issue SoapServer fault indicating an error
     * @link https://php.net/manual/zh/soapserver.fault.php
     * @param string $code <p>
     * The error code to return
     * </p>
     * @param string $string <p>
     * A brief description of the error
     * </p>
     * @param string $actor [optional] <p>
     * A string identifying the actor that caused the fault.
     * </p>
     * @param string $details [optional] <p>
     * More details of the fault
     * </p>
     * @param string $name [optional] <p>
     * The name of the fault. This can be used to select a name from a WSDL file.
     * @param string $lang [optional] since 8.5
     * </p>
     * @return void No value is returned.
     * @since 5.0
     */
    #[TentativeType]
    public function fault(
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $code,
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $string,
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $actor = '',
        #[LanguageLevelTypeAware(['8.0' => 'mixed'], default: '')] $details = null,
        #[LanguageLevelTypeAware(['8.0' => 'string'], default: '')] $name = '',
        #[PhpStormStubsElementAvailable('8.5')] string $lang = ''
    ): void {}

