    /**
 * <div id="soapserver.getlastresponse" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapServer::__getLastResponse</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4)</p><p class="refpurpose"><span class="refname">SoapServer::__getLastResponse</span> — <span class="dc-title">Returns last SOAP response</span></p> </div> <div class="refsect1 description" id="refsect1-soapserver.getlastresponse-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapServer::__getLastResponse</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span></div>  <p class="simpara">   Returns the XML sent in the last SOAP response.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    This method works only if the <span class="classname"><a href="https://php.net/manual/zh/class.soapserver.php" class="classname">SoapServer</a></span> object    was created with the <span class="literal">trace</span> option set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-soapserver.getlastresponse-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-soapserver.getlastresponse-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The last SOAP response, as an XML string.  </p> </div> <div class="refsect1 examples" id="refsect1-soapserver.getlastresponse-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 SoapServer::__getLastResponse() example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$server </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapServer</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, [</span><span style="color: #DD0000">"trace" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">handle</span><span style="color: #007700">();<br>echo </span><span style="color: #DD0000">"Response:\n" </span><span style="color: #007700">. </span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__getLastResponse</span><span style="color: #007700">() . </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * @since 8.4
     */
    public function __getLastResponse(): ?string {}
