/**
 * <div id="class.soapparam" class="reference"> <h1 class="title">The SoapParam class</h1>  <div class="partintro"><p class="verinfo">(PHP 5, PHP 7, PHP 8)</p>  <div class="section" id="soapparam.intro">   <h2 class="title">简介</h2>   <p class="para">     Represents parameter to a SOAP call.   </p>  </div>  <div class="section" id="soapparam.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">class</span> <strong class="classname"><strong class="classname">SoapParam</strong></strong>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.soapparam.php#soapparam.props.param-name">\$<var class="varname">param_name</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.soapparam.php#soapparam.props.param-data">\$<var class="varname">param_data</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/soapparam.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>)</div>   }</div>  </div>  <div class="section" id="soapparam.props">   <h2 class="title">属性</h2>   <dl>         <dt id="soapparam.props.param-data"><var class="varname">param_data</var></dt>     <dd>      <p class="para">      </p>     </dd>             <dt id="soapparam.props.param-name"><var class="varname">param_name</var></dt>     <dd>      <p class="para">      </p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link SoapParam::__construct} — SoapParam constructor</li></ul></div>
 * 
 * Represents parameter to a SOAP call.
 * @link https://php.net/manual/zh/class.soapparam.php
 */
class SoapParam
{
    /**
     * @var string
     * @since 8.1
     */
    public string $param_name;

    /**
     * @var mixed
     * @since 8.1
     */
    public mixed $param_data;

    /**
 * <div id="soapparam.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">SoapParam::__construct</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">SoapParam::__construct</span> — <span class="dc-title">SoapParam constructor</span></p> </div> <div class="refsect1 description" id="refsect1-soapparam.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>SoapParam::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>)</div>  <p class="para rdfs-comment">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.soapparam.php" class="classname">SoapParam</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapparam.construct-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">data</span></dt>     <dd>      <p class="para">       The data to pass or return. This parameter can be passed directly as PHP       value, but in this case it will be named as <span class="literal">paramN</span> and       the SOAP service may not understand it.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The parameter name.      </p>     </dd>       </dl>   </div> <div class="refsect1 examples" id="refsect1-soapparam.construct-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapParam::__construct()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">,array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                    </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">(new </span><span style="color: #9876AA">SoapParam</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #DD0000">"a"</span><span style="color: #007700">),<br>                      new </span><span style="color: #9876AA">SoapParam</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">),<br>                      new </span><span style="color: #9876AA">SoapParam</span><span style="color: #007700">(</span><span style="color: #9876AA">\$c</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapparam.construct-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__soapCall()} - Calls a SOAP function</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapVar::__construct()} - SoapVar constructor</span></li>   </ul>   </div></div>
