ge.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$actor</span><span class="initializer"> = ?</span></span><br>)</div>  <p class="para rdfs-comment">   Constructs a new SoapHeader object.  </p> </div> <div class="refsect1 parameters" id="refsect1-soapheader.construct-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">namespace</span></dt>     <dd>      <p class="para">       The namespace of the SOAP header element.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">name</span></dt>     <dd>      <p class="para">       The name of the SoapHeader object.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">data</span></dt>     <dd>      <p class="para">       A SOAP header's content. It can be a PHP value or a       <span class="classname"><a href="https://php.net/manual/zh/class.soapvar.php" class="classname">SoapVar</a></span> object.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">mustUnderstand</span></dt>     <dd>      <p class="para">       Value of the <span class="literal">mustUnderstand</span> attribute of the SOAP       header element.      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">actor</span></dt>     <dd>      <p class="para">       Value of the <span class="literal">actor</span> attribute of the SOAP header       element.      </p>     </dd>       </dl>   </div> <div class="refsect1 examples" id="refsect1-soapheader.construct-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">SoapHeader::__construct()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'location' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://localhost/soap.php"</span><span style="color: #007700">,<br>                                     </span><span style="color: #DD0000">'uri'      </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"http://test-uri/"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">__soapCall</span><span style="color: #007700">(</span><span style="color: #DD0000">"echoVoid"</span><span style="color: #007700">, </span><span style="color: #9876AA">null</span><span style="color: #007700">, </span><span style="color: #9876AA">null</span><span style="color: #007700">,<br>                new </span><span style="color: #9876AA">SoapHeader</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://soapinterop.org/echoheader/'</span><span style="color: #007700">,<br>                               </span><span style="color: #DD0000">'echoMeStringRequest'</span><span style="color: #007700">,<br>                               </span><span style="color: #DD0000">'hello world'</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-soapheader.construct-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__soapCall()} - Calls a SOAP function</span></li> 