/**
 * <div id="function.use-soap-error-handler" class="refentry"> <div class="refnamediv">  <h1 class="refname">use_soap_error_handler</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">use_soap_error_handler</span> — <span class="dc-title">Set whether to use the SOAP error handler</span></p> </div> <div class="refsect1 description" id="refsect1-function.use-soap-error-handler-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>use_soap_error_handler</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$enable</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   This function sets whether or not to use the SOAP error handler in the SOAP server.    It will return the previous value. If set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, details of errors   in a <span class="classname"><a href="https://php.net/manual/zh/class.soapserver.php" class="classname">SoapServer</a></span> application will be sent to the client   as a SOAP fault message.   If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>, the standard PHP error handler is used.   The default is to send error to the client as SOAP fault message.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.use-soap-error-handler-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">enable</span></dt>     <dd>      <p class="para">       Set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> to send error details to clients.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.use-soap-error-handler-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns the original value.  </p> </div> <div class="refsect1 seealso" id="refsect1-function.use-soap-error-handler-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link set_error_handler()} - 设置用户自定义的错误处理函数</span></li>    <li><span class="function">{@link set_exception_handler()} - 设置用户自定义的异常处理函数</span></li>   </ul>   </div></div>
 * 
 * Set whether to use the SOAP error handler
 * @link https://php.net/manual/zh/function.use-soap-error-handler.php
 * @param bool $enable [optional] <p>
 * Set to <b>TRUE</b> to send error details to clients.
 * </p>
 * @return bool the original value.
 */
function use_soap_error_handler(bool $enable = true): bool {}

/**
 * <div id="function.is-soap-fault" class="refentry"> <div class="refnamediv">  <h1 class="refname">is_soap_fault</h1>  <p class="verinfo">(PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">is_soap_fault</span> — <span class="dc-title">Checks if a SOAP call has failed</span></p> </div> <div class="refsect1 description" id="refsect1-function.is-soap-fault-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>is_soap_fault</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$object</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   This function is useful to check if the SOAP call failed, but   without using exceptions. To use it, create a   <span class="classname"><a href="https://php.net/manual/zh/class.soapclient.php" class="classname">SoapClient</a></span> object with the <span class="literal">exceptions</span>   option set to zero or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.   In this case, the SOAP method will return a special   <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> object which encapsulates the fault   details (faultcode, faultstring, faultactor and faultdetails).  </p>  <p class="para">   If <span class="literal">exceptions</span> is not set then SOAP call will throw   an exception on error.   <span class="function"><strong style="color:#CC7832">is_soap_fault()</strong></span> checks if the given   parameter is a <span class="classname"><a href="https://php.net/manual/zh/class.soapfault.php" class="classname">SoapFault</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-function.is-soap-fault-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">object</span></dt>     <dd>      <p class="para">       The object to test.      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.is-soap-fault-returnvalues">  <h3 class="title">返回值</h3>    <p class="para">   This will return <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> on error, and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-function.is-soap-fault-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">is_soap_fault()</strong></span> example</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">, array(</span><span style="color: #DD0000">'exceptions' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">();<br>if (</span><span style="color: #9876AA">is_soap_fault</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">)) {<br>    </span><span style="color: #9876AA">trigger_error</span><span style="color: #007700">(</span><span style="color: #DD0000">"SOAP Fault: (faultcode: </span><span style="color: #007700">{</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">faultcode</span><span style="color: #007700">}</span><span style="color: #DD0000">, faultstring: </span><span style="color: #007700">{</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">faultstring</span><span style="color: #007700">}</span><span style="color: #DD0000">)"</span><span style="color: #007700">, </span><span style="color: #9876AA">E_USER_ERROR</span><span style="color: #007700">);<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   <div class="example" id="example-2">    <p><strong>示例 #2 SOAP's standard method for error reporting is exceptions</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">try {<br>    </span><span style="color: #9876AA">\$client </span><span style="color: #007700">= new </span><span style="color: #9876AA">SoapClient</span><span style="color: #007700">(</span><span style="color: #DD0000">"some.wsdl"</span><span style="color: #007700">);<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$client</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">SomeFunction</span><span style="color: #007700">(</span><span style="color: #FF8000">// ... </span><span style="color: #007700">);<br>} catch (</span><span style="color: #9876AA">SoapFault \$fault</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">trigger_error</span><span style="color: #007700">(</span><span style="color: #DD0000">"SOAP Fault: (faultcode: </span><span style="color: #007700">{</span><span style="color: #9876AA">\$fault</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">faultcode</span><span style="color: #007700">}</span><span style="color: #DD0000">, faultstring: </span><span style="color: #007700">{</span><span style="color: #9876AA">\$fault</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">faultstring</span><span style="color: #007700">}</span><span style="color: #DD0000">)"</span><span style="color: #007700">, </span><span style="color: #9876AA">E_USER_ERROR</span><span style="color: #007700">);<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-function.is-soap-fault-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link SoapClient::__construct()} - SoapClient constructor</span></li>    <li><span class="methodname" style="color:#CC7832">{@link SoapFault::__construct()} - SoapFault constructor</span></li>   </ul>   </div></div>
